mapper.select:
SELECT

FROM RwaInstSpvCompany a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instSpvPromoterId = #{instSpvPromoterId}


    AND a.spvCompanyName = #{spvCompanyName}


    AND a.spvCompanyType = #{spvCompanyType}


    AND a.spvCompanyIndustry = #{spvCompanyIndustry}


    AND a.spvCompanyRegistrNo = #{spvCompanyRegistrNo}


    AND a.spvCompanyRegistrImg = #{spvCompanyRegistrImg}


    AND a.spvCompanyCountry = #{spvCompanyCountry}


    AND a.spvCompanyEmail = #{spvCompanyEmail}


    AND a.spvCompanyMobileNo = #{spvCompanyMobileNo}


    AND a.spvCompanyAddress = #{spvCompanyAddress}


    AND a.spvCompanyDesc = #{spvCompanyDesc}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}


    AND a.checkBy = #{checkBy}


    AND a.checkTime = #{checkTime}

limit 1
